package com.samsixx.pocket2droid;
import java.io.*;import java.nio.file.*;import java.security.*;import java.lang.reflect.*;import java.util.*;import org.json.*;

/** Real repository/filesystem behavior; Android device preferences are a boundary. */
public final class RomUpdateTest {
 static int checks;static final String KEY="rom-0123456789abcdef0123456789abcdef";
 static native void fileFault(String path,boolean enabled);static native int fileSyncCalls();
 static native void directoryFault(String path,int fault,int nth);static native int syncCalls();static native void crashFault(boolean value);static native void failAfter(long bytes);
 static void yes(boolean b,String why){if(!b)throw new AssertionError(why);checks++;}
 interface Action{void run()throws Exception;}
 static void refused(Action action,String why)throws Exception{try{action.run();throw new AssertionError(why);}catch(IOException expected){checks++;}}
 static String hash(File f)throws Exception{MessageDigest d=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(f)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)d.update(b,0,n);}StringBuilder s=new StringBuilder();for(byte x:d.digest())s.append(String.format(Locale.ROOT,"%02x",x&255));return s.toString();}
 static void write(File f,byte[] bytes)throws Exception{f.getParentFile().mkdirs();Files.write(f.toPath(),bytes);}
 static byte[] bytes(String s)throws Exception{return s.getBytes("UTF-8");}
 static List<String> names(RomRepository r)throws Exception{List<String> out=new ArrayList<>();for(RomProfile p:r.scan())out.add(p.filename);return out;}
 static RomProfile update(RomRepository r,String old,InputStream input,String next)throws Exception{
  return update(r,old,input,next,()->{});
 }
 static RomProfile update(RomRepository r,String old,InputStream input,String next,Runnable prepared)throws Exception{
  try{Class<?> c=Class.forName("com.samsixx.pocket2droid.RomUpdate$Identity");Object identity=Proxy.newProxyInstance(c.getClassLoader(),new Class[]{c},(p,m,a)->{prepared.run();return KEY;});Method method=RomRepository.class.getDeclaredMethod("updateRom",String.class,InputStream.class,String.class,c);method.setAccessible(true);return(RomProfile)method.invoke(r,old,input,next,identity);}
  catch(ClassNotFoundException|NoSuchMethodException missing){throw new AssertionError("Storage-preserving Update/Change ROM API is not implemented",missing);}
  catch(InvocationTargetException failure){if(failure.getCause() instanceof IOException)throw(IOException)failure.getCause();if(failure.getCause() instanceof RuntimeException)throw(RuntimeException)failure.getCause();throw failure;}
 }
 static String key(RomProfile p)throws Exception{Field field=RomProfile.class.getDeclaredField("settingsKey");field.setAccessible(true);return(String)field.get(p);}
 static final class Fixture {
  final File base,card;final RomRepository repository;RomProfile original;final String digest;final byte[] old;
  Fixture(String label,boolean wm5)throws Exception{
   base=Files.createTempDirectory("p2d-update-"+label).toFile();card=new File(base,"card");card.mkdir();repository=new RomRepository(new File(base,"pocket2droid"),new File(base,"private"),card,new Random(3));
   old=bytes(wm5?"B000FF\noriginal WM5 download":"original raw ROM");repository.importRom(new ByteArrayInputStream(bytes("other")),"Other.BIN");
   original=repository.importRom(new ByteArrayInputStream(old),"Old.BIN");repository.prepareSave(original.filename,RomRepository.SaveChoice.NEW_INSTALLATION);original=repository.getProfile(original.filename);
   try(RandomAccessFile f=new RandomAccessFile(original.storage,"rw")){f.writeInt(0x13572468);f.seek(StorageLayout.STORAGE_SIZE-4);f.writeInt(0x24681357);f.getFD().sync();}
   repository.saveSettings(original.filename,original.settings.withDisplayName("My installation").withOrientation(RomSettings.HostOrientation.LANDSCAPE).withGles(true).withGlesGpu(true));
   File meta=new File(original.storage.getParentFile(),"profile.json");JSONObject legacy=new JSONObject(new String(Files.readAllBytes(meta.toPath()),"UTF-8"));legacy.remove("settingsKey");write(meta,bytes(legacy.toString()));original=repository.getProfile(original.filename);write(new File(original.storage.getParentFile(),"nested/unknown.dat"),bytes("retained sidecar"));write(new File(card,"keep.cab"),bytes("external card"));digest=hash(original.storage);
  }
  void intact()throws Exception{RomProfile p=repository.getProfile("Old.BIN");yes(Arrays.equals(Files.readAllBytes(p.rom.toPath()),old)&&hash(p.storage).equals(digest),"Rejected update preserves original ROM and nonzero save");yes(new String(Files.readAllBytes(new File(card,"keep.cab").toPath()),"UTF-8").equals("external card"),"Storage Card is unchanged");}
 }
 static void basic()throws Exception{
  Fixture f=new Fixture("rename",false);String icon=f.original.iconId;File source=new File(f.base,"source/New.BIN");write(source,bytes("updated ROM"));String sourceHash=hash(source);
  RomProfile p;try(InputStream in=new FileInputStream(source)){p=update(f.repository,"Old.BIN",in,"New.BIN");}
  yes(p.filename.equals("New.BIN")&&p.displayName.equals("New"),"ROM identity and label change to chosen filename");
  yes(p.storage.equals(new File(f.repository.data,"New.BIN/ram-fmd.bin"))&&hash(p.storage).equals(f.digest),"Renamed installation keeps the exact nonzero storage bytes");
  yes(p.saveState.equals("READY")&&p.iconId.equals(icon)&&p.settings.card.equals(f.card)&&p.settings.glesEnabled&&p.settings.glesGpuEnabled&&p.settings.orientation==RomSettings.HostOrientation.LANDSCAPE,"Prepared state, icon, settings and custom card are retained");
  yes(Arrays.equals(Files.readAllBytes(new File(p.storage.getParentFile(),"nested/unknown.dat").toPath()),bytes("retained sidecar")),"Unknown per-ROM sidecar survives");
  yes(names(f.repository).equals(Arrays.asList("Other.BIN","New.BIN")),"Update retains one library row at its original position");yes(!new File(f.repository.roms,"Old.BIN").exists()&&!new File(f.repository.data,"Old.BIN").exists(),"Previous public identity is retired");
  yes(hash(source).equals(sourceHash),"Selected source file is untouched");yes(key(p).equals(KEY),"Prepared private-device identity is recorded");
  yes(f.repository.getProfile("Old.BIN").filename.equals("New.BIN"),"A recreated read-only settings intent follows the completed update");
  refused(()->f.repository.deleteRom("Old.BIN"),"A stale delete filename cannot redirect to the updated installation");
  RomProfile chained=update(f.repository,"New.BIN",new ByteArrayInputStream(bytes("third ROM")),"Final.BIN");yes(hash(chained.storage).equals(f.digest)&&f.repository.getProfile("Old.BIN").filename.equals("Final.BIN"),"Completed updates resolve through a chain without losing data");
  f.repository.importRom(new ByteArrayInputStream(bytes("different new-name installation")),"New.BIN");yes(f.repository.getProfile("Old.BIN").filename.equals("Final.BIN"),"A reused intermediate filename does not steal an old installation alias");
  RomProfile fresh=f.repository.importRom(new ByteArrayInputStream(bytes("new separate installation")),"Old.BIN");yes(fresh.filename.equals("Old.BIN")&&!key(fresh).equals(key(p)),"Reusing the old filename creates a separate device-settings identity");
  yes(f.repository.getProfile("Old.BIN").filename.equals("Old.BIN"),"Real recreated old filename takes precedence over an alias");
  Fixture same=new Fixture("same",false);RomProfile q=update(same.repository,"Old.BIN",new ByteArrayInputStream(bytes("replacement same name")),"Old.BIN");yes(hash(q.storage).equals(same.digest)&&q.filename.equals("Old.BIN")&&q.saveState.equals("READY"),"Same-name replacement preserves the installation");
  Fixture casing=new Fixture("case",false);RomProfile c=update(casing.repository,"Old.BIN",new ByteArrayInputStream(bytes("changed casing")),"old.bin");yes(c.filename.equals("old.bin")&&hash(c.storage).equals(casing.digest),"Case-only rename on a case-sensitive filesystem retains storage");
 }
 static void rejection()throws Exception{
  Fixture f=new Fixture("reject",false);String beforeOrder=names(f.repository).toString();
  refused(()->update(f.repository,"Old.BIN",new ByteArrayInputStream(new byte[0]),"New.BIN"),"Empty ROM must fail");f.intact();
  refused(()->update(f.repository,"Old.BIN",new ByteArrayInputStream(bytes("cab")),"New.cab"),"Only BIN input is accepted");f.intact();
  refused(()->update(f.repository,"Old.BIN",new ByteArrayInputStream(bytes("collision")),"Other.BIN"),"Another library filename cannot be overwritten");f.intact();
  File occupied=new File(f.repository.data,"Occupied.BIN");occupied.mkdir();write(new File(occupied,"keep.dat"),bytes("orphan data"));refused(()->update(f.repository,"Old.BIN",new ByteArrayInputStream(bytes("collision")),"Occupied.BIN"),"Occupied orphan data cannot be overwritten");yes(new File(occupied,"keep.dat").exists(),"Orphan data is preserved");
  InputStream broken=new InputStream(){public int read()throws IOException{throw new IOException("provider disconnected");}};refused(()->update(f.repository,"Old.BIN",broken,"New.BIN"),"Provider failure must preserve the installation");f.intact();
  InputStream huge=new InputStream(){long left=StorageLayout.MAX_ROM_SIZE+1;public int read(){if(left--<=0)return -1;return 0;}public int read(byte[] b,int at,int n){if(left==0)return -1;n=(int)Math.min(left,n);Arrays.fill(b,at,at+n,(byte)0);left-=n;return n;}};refused(()->update(f.repository,"Old.BIN",huge,"Huge.BIN"),"Oversize input is refused before changing current data");f.intact();
  Object owner=new Object();yes(SessionGuard.claim(owner,"Old.BIN"),"Fixture owns a live session");try{refused(()->update(f.repository,"Old.BIN",new ByteArrayInputStream(bytes("busy")),"New.BIN"),"An active session blocks ROM replacement");}finally{SessionGuard.release(owner);}f.intact();
  File outside=new File(f.base,"outside");outside.mkdir();Files.createSymbolicLink(new File(f.repository.roms,"Link.BIN").toPath(),new File(outside,"untouched").toPath());refused(()->update(f.repository,"Old.BIN",new ByteArrayInputStream(bytes("redirected")),"Link.BIN"),"Symlink destinations cannot redirect replacement");yes(!new File(outside,"untouched").exists(),"No redirected file was written");
  yes(names(f.repository).containsAll(Arrays.asList("Old.BIN","Other.BIN")),"Original rows remain after every rejection");
 }
 static void wm5()throws Exception{
  Fixture f=new Fixture("wm5",true);File ram=GuestRam.prepare(f.original.rom,f.original.storage.getParentFile(),f.repository.runtime);try(RandomAccessFile a=new RandomAccessFile(ram,"rw")){a.writeInt(0x51782591);a.getFD().sync();}String oldRAM=hash(ram);
  refused(()->update(f.repository,"Old.BIN",new ByteArrayInputStream(bytes("B000FF\nchanged WM5")),"Updated.BIN"),"Changed WM5 cannot silently start a different hash-bound object store");f.intact();yes(hash(ram).equals(oldRAM),"Refused WM5 update preserves retained SDRAM");
  RomProfile renamed=update(f.repository,"Old.BIN",new ByteArrayInputStream(f.old),"Renamed.BIN");File preserved=GuestRam.prepare(renamed.rom,renamed.storage.getParentFile(),f.repository.runtime);yes(hash(preserved).equals(oldRAM)&&hash(renamed.storage).equals(f.digest),"Identical WM5 rename retains real GuestRam identity and contents");
 }
 static void recovery()throws Exception{
  Fixture f=new Fixture("recover-finish",false);File newData=new File(f.repository.data,"New.BIN");directoryFault(newData.getPath(),2,6);boolean failed=false;
  try{update(f.repository,"Old.BIN",new ByteArrayInputStream(bytes("updated ROM")),"New.BIN");}catch(IOException expected){failed=true;}finally{directoryFault(newData.getPath(),0,0);}
  yes(failed,"Fixture interrupts a final new-data directory sync");RomRepository reopened=new RomRepository(f.repository.root,f.repository.runtime,f.card);RomProfile p=reopened.getProfile("Old.BIN");yes(p.filename.equals("New.BIN")&&hash(p.storage).equals(f.digest),"Interrupted finalization recovers the same saved installation");yes(names(reopened).equals(Arrays.asList("Other.BIN","New.BIN")),"Recovered update has one row and no new blank installation");
 }
 static void faultMatrix()throws Exception{
  int[][] points={{0,1},{0,3},{0,5},{0,8},{0,9},{1,1},{1,2},{1,4},{1,6},{2,1},{2,2},{3,1},{3,3}};
  for(int[] point:points){Fixture f=new Fixture("fault-"+point[0]+"-"+point[1],false);File path=point[0]==0?f.repository.runtime:point[0]==1?new File(f.repository.data,"New.BIN"):point[0]==2?f.repository.roms:f.repository.data;directoryFault(path.getPath(),2,point[1]);boolean failed=false;int calls;
   try{update(f.repository,"Old.BIN",new ByteArrayInputStream(bytes("updated ROM")),"New.BIN");}catch(IOException expected){failed=true;}finally{calls=syncCalls();directoryFault(path.getPath(),0,0);}
   yes(calls>=point[1]&&failed,"Chosen filesystem durability boundary really failed");RomRepository r=new RomRepository(f.repository.root,f.repository.runtime,f.card);List<RomProfile> all=r.scan();RomProfile installation=null;int count=0;for(RomProfile p:all)if(p.filename.equals("Old.BIN")||p.filename.equals("New.BIN")){installation=p;count++;}
   yes(count==1&&installation!=null&&installation.saveState.equals("READY")&&hash(installation.storage).equals(f.digest),"Restart retains exactly one nonzero saved installation after sync fault");yes(!new File(f.repository.runtime,"library-rom-update.pending.json").exists(),"Recovery retires the resolved update journal");
   System.out.println("Recovered durability point "+point[0]+":"+point[1]);
  }
 }
 static void partialAndCorrupt()throws Exception{
  Fixture f=new Fixture("partial",false);File data=new File(f.repository.data,"New.BIN");directoryFault(data.getPath(),2,3);
  try{update(f.repository,"Old.BIN",new ByteArrayInputStream(bytes("updated ROM")),"New.BIN");throw new AssertionError("Fault not reached");}catch(IOException expected){}finally{directoryFault(data.getPath(),0,0);}
  File partial=new File(data,"ram-fmd.bin");yes(partial.isFile(),"Journal-owned copied save exists at interrupted boundary");try(RandomAccessFile a=new RandomAccessFile(partial,"rw")){a.setLength(1234567);a.getFD().sync();}
  RomProfile p=new RomRepository(f.repository.root,f.repository.runtime,f.card).getProfile("Old.BIN");yes(hash(p.storage).equals(f.digest)&&p.filename.equals("New.BIN"),"A partial owned copy is verified and recopied from its preserved snapshot");
  Fixture corrupt=new Fixture("corrupt",false);File newData=new File(corrupt.repository.data,"New.BIN");directoryFault(newData.getPath(),2,3);
  try{update(corrupt.repository,"Old.BIN",new ByteArrayInputStream(bytes("updated ROM")),"New.BIN");throw new AssertionError("Fault not reached");}catch(IOException expected){}finally{directoryFault(newData.getPath(),0,0);}
  File unexpected=new File(newData,"ram-fmd.bin");try(RandomAccessFile a=new RandomAccessFile(unexpected,"rw")){a.seek(0);a.writeInt(0x77777777);a.getFD().sync();}String unexpectedHash=hash(unexpected);
  refused(()->new RomRepository(corrupt.repository.root,corrupt.repository.runtime,corrupt.card).scan(),"Unexpected changed output blocks recovery rather than discarding it");yes(hash(unexpected).equals(unexpectedHash)&&hash(corrupt.original.storage).equals(corrupt.digest),"Both unexpected output and authoritative old save remain intact");
  Fixture malformed=new Fixture("bad-record",false);write(new File(malformed.repository.runtime,"library-rom-update.pending.json"),bytes("{\"schema\":999}"));refused(()->malformed.repository.scan(),"Invalid recovery record cannot publish or reset storage");yes(hash(malformed.original.storage).equals(malformed.digest),"Corrupt journal leaves saved bytes intact");
 }
 static void copyFailure()throws Exception{Fixture f=new Fixture("copy-failure",false);boolean failed=false;try{update(f.repository,"Old.BIN",new ByteArrayInputStream(bytes("updated ROM")),"New.BIN",()->failAfter(65536));}catch(IOException expected){failed=true;}finally{failAfter(-1);}yes(failed,"Actual native exclusive copy failed partway through saved-data output");RomProfile p=new RomRepository(f.repository.root,f.repository.runtime,f.card).getProfile("Old.BIN");yes(p.filename.equals("New.BIN")&&hash(p.storage).equals(f.digest),"Native partial copy resumes without losing or zeroing the installation");}
 static void crashChild(String[]args)throws Exception{File base=new File(args[1]);RomRepository r=new RomRepository(new File(base,"pocket2droid"),new File(base,"private"),new File(base,"card"));r.getProfile("Old.BIN");int group=Integer.parseInt(args[2]),nth=Integer.parseInt(args[3]);File path=group==0?r.runtime:group==1?new File(r.data,"New.BIN"):r.roms;directoryFault(path.getPath(),2,nth);crashFault(true);update(r,"Old.BIN",new ByteArrayInputStream(bytes("updated ROM")),args[4]);throw new AssertionError("Crash boundary was not reached");}
 static void crashRecovery()throws Exception{for(String[] point:new String[][]{{"0","4","New.BIN"},{"1","6","New.BIN"},{"2","2","New.BIN"},{"2","1","Old.BIN"}}){Fixture f=new Fixture("process-crash",false);File log=new File(f.base,"child.log");Process process=new ProcessBuilder(System.getProperty("java.home")+"/bin/java","-Djava.library.path="+System.getProperty("java.library.path"),"-cp",System.getProperty("java.class.path"),RomUpdateTest.class.getName(),"crash-child",f.base.getPath(),point[0],point[1],point[2]).redirectErrorStream(true).redirectOutput(log).start();yes(process.waitFor()==93,"Child really died at a durability boundary: "+new String(Files.readAllBytes(log.toPath()),"UTF-8"));RomRepository reopened=new RomRepository(f.repository.root,f.repository.runtime,f.card);RomProfile p=reopened.getProfile("Old.BIN");yes(p.filename.equals(point[2])&&hash(p.storage).equals(f.digest)&&p.saveState.equals("READY"),"Fresh process recovery keeps the original nonzero installation");yes(names(reopened).size()==2,"Process death creates no duplicate or fresh installation");}}
 static void ownerInterrupted()throws Exception{for(int length:new int[]{0,12}){Fixture f=new Fixture("partial-owner",false);File data=new File(f.repository.data,"New.BIN");directoryFault(data.getPath(),2,1);try{update(f.repository,"Old.BIN",new ByteArrayInputStream(bytes("updated ROM")),"New.BIN");throw new AssertionError("Fault not reached");}catch(IOException expected){}finally{directoryFault(data.getPath(),0,0);}File[] markers=data.listFiles((d,n)->n.startsWith(".p2d-update-"));yes(markers!=null&&markers.length==1&&data.list().length==1,"Only the interrupted ownership checkpoint is present");try(RandomAccessFile a=new RandomAccessFile(markers[0],"rw")){a.setLength(length);a.getFD().sync();}RomProfile recovered=new RomRepository(f.repository.root,f.repository.runtime,f.card).getProfile("Old.BIN");yes(recovered.filename.equals("New.BIN")&&hash(recovered.storage).equals(f.digest),"A partial ownership checkpoint resumes the original installation");}}
 static void wm5Invalid()throws Exception{for(int fault=0;fault<4;fault++){Fixture f=new Fixture("wm5-invalid",true);File ram=GuestRam.prepare(f.original.rom,f.original.storage.getParentFile(),f.repository.runtime),ready=new File(ram.getPath()+".ready");if(fault==0)ram.delete();if(fault==1)try(RandomAccessFile a=new RandomAccessFile(ram,"rw")){a.setLength(1);}if(fault==2)write(ready,bytes("corrupt"));if(fault==3)ready.delete();refused(()->update(f.repository,"Old.BIN",new ByteArrayInputStream(f.old),"New.BIN"),"Invalid/missing established WM5 state must reject rename");f.intact();}}
 static void completedInterrupted()throws Exception{Fixture f=new Fixture("completed-prefix",false);File newData=new File(f.repository.data,"New.BIN");directoryFault(newData.getPath(),2,6);try{update(f.repository,"Old.BIN",new ByteArrayInputStream(bytes("updated ROM")),"New.BIN");throw new AssertionError("Fault not reached");}catch(IOException expected){}finally{directoryFault(newData.getPath(),0,0);}File pending=new File(f.repository.runtime,"library-rom-update.pending.json");JSONObject r=new JSONObject(new String(Files.readAllBytes(pending.toPath()),"UTF-8"));File completed=new File(f.repository.data,".rom-updates/"+r.getString("id")+"/completed.txt");try(RandomAccessFile a=new RandomAccessFile(completed,"rw")){a.setLength(8);a.getFD().sync();}RomProfile p=new RomRepository(f.repository.root,f.repository.runtime,f.card).getProfile("Old.BIN");yes(p.filename.equals("New.BIN")&&hash(p.storage).equals(f.digest),"Partial completion stamp resumes verified installation");}
 static void freshIdentity()throws Exception{Fixture f=new Fixture("fresh-key",false);RomProfile renamed=update(f.repository,"Old.BIN",new ByteArrayInputStream(bytes("updated")),"New.BIN"),fresh=f.repository.importRom(new ByteArrayInputStream(bytes("different")),"Old.BIN");yes(fresh.settingsKey.matches("rom-[0-9a-f]{32}")&&!fresh.settingsKey.equals(renamed.settingsKey),"Reused filename gets a new stable settings key instead of inheriting filename-keyed calibration/cache");}
 static void staleMutation()throws Exception{Fixture f=new Fixture("stale-mutation",false);String prior=f.original.settingsKey;update(f.repository,"Old.BIN",new ByteArrayInputStream(bytes("updated")),"New.BIN");RomProfile fresh=f.repository.importRom(new ByteArrayInputStream(bytes("different")),"Old.BIN");for(String operation:new String[]{"deleteRom","saveSettings","updateRom"}){try{Method m;if(operation.equals("deleteRom"))m=RomRepository.class.getDeclaredMethod(operation,String.class,String.class);else if(operation.equals("saveSettings"))m=RomRepository.class.getDeclaredMethod(operation,String.class,String.class,RomSettings.class);else m=RomRepository.class.getDeclaredMethod(operation,String.class,String.class,InputStream.class,String.class,RomUpdate.Identity.class);m.setAccessible(true);try{if(operation.equals("deleteRom"))m.invoke(f.repository,"Old.BIN",prior);else if(operation.equals("saveSettings"))m.invoke(f.repository,"Old.BIN",prior,fresh.settings.withDisplayName("stale"));else m.invoke(f.repository,"Old.BIN",prior,new ByteArrayInputStream(bytes("bad")),"Wrong.BIN",(RomUpdate.Identity)(p->KEY));throw new AssertionError("Stale "+operation+" must not affect replacement installation");}catch(InvocationTargetException e){if(!(e.getCause() instanceof IOException))throw e;checks++;}}catch(NoSuchMethodException e){throw new AssertionError("Mutation API must fence the selected installation key",e);}}yes(f.repository.getProfile("Old.BIN").settingsKey.equals(fresh.settingsKey)&&fresh.rom.isFile(),"Reused filename installation remains untouched");}
 static void fileSyncRecovery()throws Exception{Fixture f=new Fixture("file-sync",false);File target=new File(f.repository.data,"New.BIN/ram-fmd.bin");try{update(f.repository,"Old.BIN",new ByteArrayInputStream(bytes("updated ROM")),"New.BIN",()->fileFault(target.getPath(),true));throw new AssertionError("Native file fsync failure not reached");}catch(IOException expected){}yes(fileSyncCalls()>0&&target.length()==StorageLayout.STORAGE_SIZE,"Real fsync fails after all saved bytes were copied");fileFault(target.getPath(),true);refused(()->new RomRepository(f.repository.root,f.repository.runtime,f.card).scan(),"Recovery must retry file fsync and block while it fails");yes(fileSyncCalls()>0&&hash(f.original.storage).equals(f.digest),"Failed resync preserves authoritative original save");fileFault(target.getPath(),false);RomProfile recovered=new RomRepository(f.repository.root,f.repository.runtime,f.card).getProfile("Old.BIN");yes(recovered.filename.equals("New.BIN")&&hash(recovered.storage).equals(f.digest),"Recovery completes only after matching file is synchronized");}
 static void checkpointSync()throws Exception{for(String stamp:new String[]{"rom-publication.started","completed.txt"}){Fixture f=new Fixture("checkpoint-sync",false);File[] target={null};try{update(f.repository,"Old.BIN",new ByteArrayInputStream(bytes("updated ROM")),"New.BIN",()->{File[] ops=new File(f.repository.data,".rom-updates").listFiles();target[0]=new File(ops[0],stamp);fileFault(target[0].getPath(),true);});throw new AssertionError("Checkpoint sync failure not reached");}catch(IOException expected){}yes(fileSyncCalls()>0&&target[0].length()>0,"Real Java file fsync failed after checkpoint writing");fileFault(target[0].getPath(),true);refused(()->new RomRepository(f.repository.root,f.repository.runtime,f.card).scan(),"Recovery must retry checkpoint file durability");yes(fileSyncCalls()>0,"Recovery actually retries checkpoint fsync");fileFault(target[0].getPath(),false);RomProfile p=new RomRepository(f.repository.root,f.repository.runtime,f.card).getProfile("Old.BIN");yes(p.filename.equals("New.BIN")&&hash(p.storage).equals(f.digest),"Durable checkpoint retry retains installation");}}
 public static void main(String[]args)throws Exception{if(args.length==0||args[0].equals("basic"))basic();else if(args[0].equals("reject"))rejection();else if(args[0].equals("wm5"))wm5();else if(args[0].equals("recovery"))recovery();else if(args[0].equals("faults"))faultMatrix();else if(args[0].equals("partial"))partialAndCorrupt();else if(args[0].equals("wm5-invalid"))wm5Invalid();else if(args[0].equals("completed"))completedInterrupted();else if(args[0].equals("fresh-key"))freshIdentity();else if(args[0].equals("stale"))staleMutation();else if(args[0].equals("checkpoint-sync"))checkpointSync();else if(args[0].equals("file-sync"))fileSyncRecovery();else if(args[0].equals("owner"))ownerInterrupted();else if(args[0].equals("copy-failure"))copyFailure();else if(args[0].equals("crashes"))crashRecovery();else if(args[0].equals("crash-child"))crashChild(args);else throw new IllegalArgumentException();System.out.println("PASS ROM update "+checks+" real filesystem assertions");}
}
